package com.sabyeguyz.clinic.payment; import java.util.List; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/payment-methods") public class PaymentMethodController { private final PaymentMethodRepository repo; public PaymentMethodController(PaymentMethodRepository repo){this.repo=repo;} record Request(@jakarta.validation.constraints.NotBlank String code,@jakarta.validation.constraints.NotBlank String name){} record Response(Long id,String code,String name,boolean active){} private Response out(PaymentMethod p){return new Response(p.getId(),p.getCode(),p.getName(),p.isActive());} @GetMapping List<Response> list(){return repo.findAllByOrderByName().stream().map(this::out).toList();} @PostMapping @org.springframework.web.bind.annotation.ResponseStatus(org.springframework.http.HttpStatus.CREATED) Response create(@RequestBody @jakarta.validation.Valid Request r){if(repo.findByCode(r.code().trim().toUpperCase()).isPresent()) throw new IllegalArgumentException("รหัสช่องทางชำระเงินซ้ำ");return out(repo.save(new PaymentMethod(r.code().trim().toUpperCase(),r.name().trim())));} @PutMapping("/{id}") Response update(@PathVariable Long id,@RequestBody @jakarta.validation.Valid Request r){PaymentMethod p=repo.findById(id).orElseThrow(()->new IllegalArgumentException("ไม่พบช่องทางชำระเงิน"));p.update(r.code().trim().toUpperCase(),r.name().trim());return out(repo.save(p));} @PatchMapping("/{id}/activate") Response activate(@PathVariable Long id){PaymentMethod p=repo.findById(id).orElseThrow(()->new IllegalArgumentException("ไม่พบช่องทางชำระเงิน"));p.activate();return out(repo.save(p));} @DeleteMapping("/{id}") @org.springframework.web.bind.annotation.ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT) void delete(@PathVariable Long id){PaymentMethod p=repo.findById(id).orElseThrow(()->new IllegalArgumentException("ไม่พบช่องทางชำระเงิน"));p.deactivate();repo.save(p);} }

